mapper.update:
UPDATE PRODUCT_COMMENT
   SET PRD_CMT_CN      = #{prdCmtCn},
       PRD_CMT_UPDT_ID = #{prdCmtUpdtId}
 WHERE PRD_CMT_SN = #{prdCmtSn}
   AND PRD_CMT_TYPE_CD = 'PRDC0007'

UPDATE PRODUCT_COMMENT
   SET PRD_CMT_CN      = #{prdCmtCn},
       PRD_CMT_UPDT_ID = #{prdCmtUpdtId}
 WHERE PRD_CMT_SN      = #{prdCmtSn}
   AND PRD_CMT_TYPE_CD = 'PRDC0006'
   AND NOT EXISTS (
       SELECT 1 FROM (
           SELECT PRD_CMT_SN FROM PRODUCT_COMMENT
            WHERE PRD_CMT_PARENT_SN = #{prdCmtSn}
              AND PRD_CMT_TYPE_CD = 'PRDC0007'
       ) r
   )
